<?php if ($d['isAdmin']): ?><label class="row g8 sm"><span class="sl-toggle on" role="switch" aria-checked="true" aria-label="Shared"><input type="hidden" name="shared" value="1"></span>Share with the whole team</label><?php endif; ?>
<div class="row g8"><button type="submit" class="sl-btn">Save</button><button type="button" class="sl-btn ghost" data-sl-close>Cancel</button></div></form></div>
<script>
document.addEventListener('click', function (e) {
  var b = e.target.closest('[data-pb-kb], [data-pb-canned], [data-pb-new]');
  if (!b) return;
  var f = document.getElementById(b.getAttribute('data-sl-open') + '-form'); if (!f) return;
  f.reset(); f.id.value = 0;
  var data = JSON.parse(b.getAttribute('data-pb-kb') || b.getAttribute('data-pb-canned') || '{}');
  Object.keys(data).forEach(function (k) { if (f.elements[k] && k !== 'shared') f.elements[k].value = data[k] == null ? '' : data[k]; });
  var sw = f.querySelector('.sl-toggle'); if (sw && 'shared' in data) { sw.classList.toggle('on', !!data.shared); sw.querySelector('input').value = data.shared ? 1 : 0; }
});
<?php if ($d['edit']['kb']): ?>document.addEventListener('DOMContentLoaded', function () { var b = document.querySelector('[data-pb-kb*=\'"id":<?= (int) $d['edit']['kb'] ?>,\']'); if (b) b.click(); });<?php endif; ?>
</script>
